// 1:1 mirrors of simple FFI enums. Generated by a one-off script; edit by hand.
import DashWalletCore

/// dash-spv sync phases, in the order they run.
public enum SyncPhase: Sendable, Hashable, CaseIterable {
    case headers, filterHeaders, filters, masternodes

    init(_ ffi: DashWalletCore.SyncPhase) {
        switch ffi {
        case .headers: self = .headers
        case .filterHeaders: self = .filterHeaders
        case .filters: self = .filters
        case .masternodes: self = .masternodes
        }
    }

    var ffi: DashWalletCore.SyncPhase {
        switch self {
        case .headers: .headers
        case .filterHeaders: .filterHeaders
        case .filters: .filters
        case .masternodes: .masternodes
        }
    }
}

/// Vault lock state (DESIGN-opus §1.8).
