    case noVault, noKeys, unencrypted, locked, unlockedMixingOnly, unlocked

    init(_ ffi: DashWalletCore.VaultLockState) {
        switch ffi {
        case .noVault: self = .noVault
        case .noKeys: self = .noKeys
        case .unencrypted: self = .unencrypted
        case .locked: self = .locked
        case .unlockedMixingOnly: self = .unlockedMixingOnly
        case .unlocked: self = .unlocked
        }
    }

    var ffi: DashWalletCore.VaultLockState {
        switch self {
        case .noVault: .noVault
        case .noKeys: .noKeys
        case .unencrypted: .unencrypted
        case .locked: .locked
        case .unlockedMixingOnly: .unlockedMixingOnly
        case .unlocked: .unlocked
        }
    }
}

